using MongoDB.Driver;
using MongoDB.Bson;
using Microsoft.AspNetCore.Identity;
using NutriPlate.Api.Models;
using NutriPlate.Api.Configuration;
using Microsoft.Extensions.Options;
namespace NutriPlate.Api.Services;
public class NutriPlateService {
 private readonly IMongoCollection<Recipe> recipes; private readonly IMongoCollection<AppUser> users; private readonly IMongoCollection<MealPlan> plans; private readonly IMongoCollection<GroceryList> groceries; private readonly PasswordHasher<AppUser> hasher = new();
 public NutriPlateService(IMongoDatabase db){recipes=db.GetCollection<Recipe>("Recipes");users=db.GetCollection<AppUser>("Users");plans=db.GetCollection<MealPlan>("MealPlans");groceries=db.GetCollection<GroceryList>("GroceryLists");}
 public async Task EnsureIndexesAndSeed(CancellationToken ct=default){
  await users.Indexes.CreateOneAsync(new CreateIndexModel<AppUser>(Builders<AppUser>.IndexKeys.Ascending(x=>x.Email),new CreateIndexOptions{Unique=true}),cancellationToken:ct);
  await recipes.Indexes.CreateOneAsync(new CreateIndexModel<Recipe>(Builders<Recipe>.IndexKeys.Text(x=>x.Name).Text(x=>x.Description)),cancellationToken:ct);
  if(await recipes.CountDocumentsAsync(FilterDefinition<Recipe>.Empty,cancellationToken:ct)==0) await recipes.InsertManyAsync(SeedRecipes(),cancellationToken:ct);
 }
 private static List<Recipe> SeedRecipes()=>[
 new(){Id=ObjectId.GenerateNewId().ToString(),Name="Green Goddess Grain Bowl",Description="A fresh bowl with quinoa, avocado, greens, and lemon dressing.",PrepMinutes=20,Servings=2,Difficulty="Easy",Cuisine="Mediterranean",DietaryTags=["Vegetarian","Gluten-free"],Nutrition=new(){Calories=420,Protein=14,Carbohydrates=52,Fat=18},Ingredients=[new(){Name="quinoa",Quantity=1,Unit="cup"},new(){Name="avocado",Quantity=1,Unit="item"},new(){Name="spinach",Quantity=2,Unit="cups"},new(){Name="lemon",Quantity=1,Unit="item"}],Instructions=["Cook quinoa according to package directions.","Slice avocado and rinse the greens.","Whisk lemon juice with olive oil and season lightly.","Arrange in bowls and drizzle with dressing."]},
 new(){Id=ObjectId.GenerateNewId().ToString(),Name="Tomato Basil Pasta",Description="Comforting pasta tossed with tomatoes, basil, and a little olive oil.",PrepMinutes=25,Servings=2,Difficulty="Easy",Cuisine="Italian",DietaryTags=["Vegetarian"],Nutrition=new(){Calories=510,Protein=16,Carbohydrates=78,Fat=14},Ingredients=[new(){Name="pasta",Quantity=200,Unit="g"},new(){Name="tomatoes",Quantity=3,Unit="items"},new(){Name="basil",Quantity=10,Unit="g"},new(){Name="olive oil",Quantity=1,Unit="tbsp"}],Instructions=["Boil pasta in salted water until tender.","Chop tomatoes and warm them in olive oil.","Toss pasta with tomato sauce and torn basil.","Serve warm."]},
 new(){Id=ObjectId.GenerateNewId().ToString(),Name="Chickpea Coconut Curry",Description="A cozy chickpea curry with gentle spices and creamy coconut.",PrepMinutes=30,Servings=3,Difficulty="Easy",Cuisine="Indian",DietaryTags=["Vegan","Dairy-free"],Nutrition=new(){Calories=460,Protein=17,Carbohydrates=55,Fat=20},Ingredients=[new(){Name="chickpeas",Quantity=2,Unit="cups"},new(){Name="coconut milk",Quantity=1,Unit="can"},new(){Name="onion",Quantity=1,Unit="item"},new(){Name="curry powder",Quantity=2,Unit="tsp"}],Instructions=["Dice onion and soften in a pan.","Stir in curry powder and chickpeas.","Add coconut milk and simmer for 15 minutes.","Serve with rice if desired."]},
 new(){Id=ObjectId.GenerateNewId().ToString(),Name="Berry Overnight Oats",Description="An easy make-ahead breakfast with oats, berries, and yogurt.",PrepMinutes=10,Servings=1,Difficulty="Easy",Cuisine="Modern",DietaryTags=["Vegetarian"],Nutrition=new(){Calories=330,Protein=15,Carbohydrates=48,Fat=8},Ingredients=[new(){Name="rolled oats",Quantity=0.5,Unit="cup"},new(){Name="yogurt",Quantity=0.5,Unit="cup"},new(){Name="berries",Quantity=0.75,Unit="cup"},new(){Name="chia seeds",Quantity=1,Unit="tsp"}],Instructions=["Combine oats, yogurt, and chia seeds.","Cover and refrigerate overnight.","Top with berries before serving."]},
 new(){Id=ObjectId.GenerateNewId().ToString(),Name="Lemon Herb Chickpea Salad",Description="Bright chickpeas, crunchy vegetables, and a lemon-herb dressing.",PrepMinutes=15,Servings=2,Difficulty="Easy",Cuisine="Mediterranean",DietaryTags=["Vegan","Gluten-free"],Nutrition=new(){Calories=290,Protein=11,Carbohydrates=37,Fat=11},Ingredients=[new(){Name="chickpeas",Quantity=1.5,Unit="cups"},new(){Name="cucumber",Quantity=1,Unit="item"},new(){Name="tomatoes",Quantity=2,Unit="items"},new(){Name="lemon",Quantity=1,Unit="item"}],Instructions=["Rinse and drain chickpeas.","Dice cucumber and tomatoes.","Mix lemon juice, herbs, and olive oil.","Toss everything together and chill briefly."]}
 ];
 public Task<List<Recipe>> ListRecipes(string? search,CancellationToken ct=default){var f=string.IsNullOrWhiteSpace(search)?FilterDefinition<Recipe>.Empty:Builders<Recipe>.Filter.Or(Builders<Recipe>.Filter.Regex(x=>x.Name,new BsonRegularExpression(search,"i")),Builders<Recipe>.Filter.Regex(x=>x.Description,new BsonRegularExpression(search,"i")),Builders<Recipe>.Filter.Regex("Ingredients.Name",new BsonRegularExpression(search,"i")));return recipes.Find(f).Limit(100).ToListAsync(ct);}
 public Task<Recipe?> GetRecipe(string id,CancellationToken ct=default)=>recipes.Find(x=>x.Id==id).FirstOrDefaultAsync(ct);
 public async Task<AppUser?> FindUser(string email,CancellationToken ct=default)=>await users.Find(x=>x.Email==email.ToLowerInvariant()).FirstOrDefaultAsync(ct);
 public async Task<AppUser> Register(string email,string password,string displayName,CancellationToken ct=default){email=email.Trim().ToLowerInvariant();if(await FindUser(email,ct)!=null)throw new InvalidOperationException("An account with this email already exists.");var u=new AppUser{Id=ObjectId.GenerateNewId().ToString(),Email=email,DisplayName=displayName.Trim()};u.PasswordHash=hasher.HashPassword(u,password);await users.InsertOneAsync(u,cancellationToken:ct);return u;}
 public bool VerifyPassword(AppUser user,string password)=>hasher.VerifyHashedPassword(user,user.PasswordHash,password)!=PasswordVerificationResult.Failed;
 public Task<AppUser?> GetUser(string id,CancellationToken ct=default)=>users.Find(x=>x.Id==id).FirstOrDefaultAsync(ct);
 public async Task<AppUser> UpdateProfile(string id,string name,List<string>? prefs,List<string>? restrictions,CancellationToken ct=default){var u=await GetUser(id,ct)??throw new KeyNotFoundException("User not found.");u.DisplayName=name.Trim();u.DietaryPreferences=prefs??[];u.FoodRestrictions=restrictions??[];await users.ReplaceOneAsync(x=>x.Id==id,u,cancellationToken:ct);return u;}
 public async Task<List<Recipe>> Favorites(string userId,CancellationToken ct=default){var u=await GetUser(userId,ct)??throw new KeyNotFoundException("User not found.");return await recipes.Find(x=>u.FavoriteRecipeIds.Contains(x.Id!)).ToListAsync(ct);}
 public async Task SetFavorite(string userId,string recipeId,bool favorite,CancellationToken ct=default){if(await GetRecipe(recipeId,ct)==null)throw new KeyNotFoundException("Recipe not found.");var update=favorite?Builders<AppUser>.Update.AddToSet(x=>x.FavoriteRecipeIds,recipeId):Builders<AppUser>.Update.Pull(x=>x.FavoriteRecipeIds,recipeId);await users.UpdateOneAsync(x=>x.Id==userId,update,cancellationToken:ct);}
 public Task<List<MealPlan>> GetPlans(string uid,CancellationToken ct=default)=>plans.Find(x=>x.UserId==uid).ToListAsync(ct);
 public async Task<MealPlan> CreatePlan(string uid,string name,string start,string end,CancellationToken ct=default){if(!DateOnly.TryParse(start,out var s)||!DateOnly.TryParse(end,out var e)||e<s||e.DayNumber-s.DayNumber>13)throw new ArgumentException("Provide valid dates; end date must be on/after start date and plans may span at most 14 days.");var p=new MealPlan{Id=ObjectId.GenerateNewId().ToString(),UserId=uid,Name=name.Trim(),StartDate=start,EndDate=end};await plans.InsertOneAsync(p,cancellationToken:ct);return p;}
 public async Task<MealPlan> AddMeal(string uid,string pid,string rid,string date,string type,int servings,CancellationToken ct=default){var p=await plans.Find(x=>x.Id==pid&&x.UserId==uid).FirstOrDefaultAsync(ct)??throw new KeyNotFoundException("Meal plan not found.");var r=await GetRecipe(rid,ct)??throw new KeyNotFoundException("Recipe not found.");if(!DateOnly.TryParse(date,out var d)||d<DateOnly.Parse(p.StartDate)||d>DateOnly.Parse(p.EndDate))throw new ArgumentException("Meal date must be inside the plan date range.");if(!new[]{"Breakfast","Lunch","Dinner","Snack"}.Contains(type))throw new ArgumentException("Meal type must be Breakfast, Lunch, Dinner, or Snack.");if(servings<1||servings>20)throw new ArgumentException("Servings must be between 1 and 20.");p.Meals.Add(new(){RecipeId=rid,RecipeName=r.Name,Date=date,MealType=type,Servings=servings,Nutrition=r.Nutrition});await plans.ReplaceOneAsync(x=>x.Id==pid&&x.UserId==uid,p,cancellationToken:ct);return p;}
 public async Task RemoveMeal(string uid,string pid,string mid,CancellationToken ct=default){var p=await plans.Find(x=>x.Id==pid&&x.UserId==uid).FirstOrDefaultAsync(ct)??throw new KeyNotFoundException("Meal plan not found.");p.Meals.RemoveAll(m=>m.Id==mid);await plans.ReplaceOneAsync(x=>x.Id==pid&&x.UserId==uid,p,cancellationToken:ct);}
 public Task<List<GroceryList>> GetGroceries(string uid,CancellationToken ct=default)=>groceries.Find(x=>x.UserId==uid).ToListAsync(ct);
 public async Task<GroceryList> GenerateGroceries(string uid,string pid,CancellationToken ct=default){var p=await plans.Find(x=>x.Id==pid&&x.UserId==uid).FirstOrDefaultAsync(ct)??throw new KeyNotFoundException("Meal plan not found.");var aggregate=new Dictionary<string,GroceryItem>(StringComparer.OrdinalIgnoreCase);foreach(var meal in p.Meals){var r=await GetRecipe(meal.RecipeId,ct);if(r==null)continue;foreach(var ing in r.Ingredients){var key=$"{ing.Name.Trim().ToLowerInvariant()}|{ing.Unit.Trim().ToLowerInvariant()}";if(aggregate.TryGetValue(key,out var existing))existing.Quantity+=ing.Quantity*meal.Servings/r.Servings;else aggregate[key]=new(){Name=ing.Name,Quantity=Math.Round(ing.Quantity*meal.Servings/r.Servings,2),Unit=ing.Unit};}}var list=new GroceryList{Id=ObjectId.GenerateNewId().ToString(),UserId=uid,Name=$"Groceries · {p.Name}",MealPlanId=pid,Items=aggregate.Values.ToList()};await groceries.InsertOneAsync(list,cancellationToken:ct);return list;}
 public async Task<GroceryList> AddGrocery(string uid,string lid,string name,double qty,string unit,CancellationToken ct=default){var l=await groceries.Find(x=>x.Id==lid&&x.UserId==uid).FirstOrDefaultAsync(ct)??throw new KeyNotFoundException("Grocery list not found.");l.Items.Add(new(){Name=name.Trim(),Quantity=qty,Unit=unit.Trim()});l.UpdatedAt=DateTime.UtcNow;await groceries.ReplaceOneAsync(x=>x.Id==lid&&x.UserId==uid,l,cancellationToken:ct);return l;}
 public async Task<GroceryList> ToggleGrocery(string uid,string lid,string iid,bool purchased,CancellationToken ct=default){var l=await groceries.Find(x=>x.Id==lid&&x.UserId==uid).FirstOrDefaultAsync(ct)??throw new KeyNotFoundException("Grocery list not found.");var i=l.Items.FirstOrDefault(x=>x.Id==iid)??throw new KeyNotFoundException("Grocery item not found.");i.Purchased=purchased;l.UpdatedAt=DateTime.UtcNow;await groceries.ReplaceOneAsync(x=>x.Id==lid&&x.UserId==uid,l,cancellationToken:ct);return l;}
 public async Task RemoveGrocery(string uid,string lid,string iid,CancellationToken ct=default){var l=await groceries.Find(x=>x.Id==lid&&x.UserId==uid).FirstOrDefaultAsync(ct)??throw new KeyNotFoundException("Grocery list not found.");l.Items.RemoveAll(x=>x.Id==iid);l.UpdatedAt=DateTime.UtcNow;await groceries.ReplaceOneAsync(x=>x.Id==lid&&x.UserId==uid,l,cancellationToken:ct);}
 public async Task DeleteGrocery(string uid,string lid,CancellationToken ct=default){var result=await groceries.DeleteOneAsync(x=>x.Id==lid&&x.UserId==uid,ct);if(result.DeletedCount==0)throw new KeyNotFoundException("Grocery list not found.");}
 public async Task DeletePlan(string uid,string pid,CancellationToken ct=default){var result=await plans.DeleteOneAsync(x=>x.Id==pid&&x.UserId==uid,ct);if(result.DeletedCount==0)throw new KeyNotFoundException("Meal plan not found.");}
}
